for i, demo in enumerate(demos):
    inp = demo['input']
    outp = demo['output']

    changes = {}
    for r in range(len(inp)):
        for c in range(len(inp[r])):
            if inp[r][c] != outp[r][c]:
                changes.setdefault(inp[r][c], []).append((r, c))

    if not changes:
        continue

    changed_old = list(changes.keys())[0]
    new_color = outp[changes[changed_old][0][0]][changes[changed_old][0][1]]

    freq = Counter(sum(inp, []))

    # Sort components by size
    same_color_cells = []
    for r in range(len(inp)):
        for c in range(len(inp[r])):
            if inp[r][c] == changed_old:
                same_color_cells.append((r, c))

    visited = set()
    components = []
    for start in same_color_cells:
        if start in visited:
            continue
        comp = []
        stack = [start]
        while stack:
            cur = stack.pop()
            if cur in visited:
                continue
            visited.add(cur)
            comp.append(cur)
            r, c = cur
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if (nr, nc) in same_color_cells and (nr, nc) not in visited:
                    stack.append((nr, nc))
        components.append(comp)

    sorted_comps = sorted(components, key=len, reverse=True)

    print(f"Demo {i}: Background color count = {freq[('0',inp[(0,0)])[0]] if isinstance(('0',inp[(0,0)]), tuple) else freq[None]}")

    for j, comp in enumerate(sorted_comps):
        if not comp:
            continue
        min_r = min(r for r,c in comp)
        max_r = max(r for r,c in comp)
        min_c = min(c for r,c in comp)
        max_c = max(c for r,c in comp)
        touches_boundary = (min_r == 0 or max_r == len(inp)-1 or 
                          min_c == 0 or max_c == len(inp[0])-1)

        is_changed = any((r,c) in changes[changed_old] for r,c in comp)

        # Print bbox content as ASCII
        bbox_grid = []
        for r in range(min_r, max_r+1):
            row = []
            for c in range(min_c, max_c+1):
                color = inp[r][c]
                if color == changed_old:
                    row.append('#')
                else:
                    row.append(' ')
            bbox_grid.append("".join(row))

        print(f"Comp {j}: size={len(comp)}, touches_bd={touches_boundary}, changed={is_changed}")
        if is_changed:
            for line in bbox_grid:
                print(f"  {line}")
    print()

